// VALIDATION: compile-pass
// A dependent-base inherited constructor template participates in construction.

struct arg
{
  int value;

  explicit arg(int v)
    : value(v)
  {
  }
};

template <typename T>
struct base
{
  int value;

  template <typename U>
  explicit base(U&& u)
    : value(static_cast<U&&>(u).value)
  {
  }
};

template <typename T>
struct derived : base<T>
{
  using base<T>::base;
};

int main()
{
  arg a(7);
  derived<int> d(static_cast<arg&&>(a));
  return d.value == 7 ? 0 : 1;
}

// VALIDATION: compile-pass
// Constructor-template participation must survive when inherited through a
// class-template partial specialization.

struct impl {
  template <class Self>
  void operator()(Self&) {
  }
};

struct work {
};

struct handler {
};

template <class Impl, class Work, class Handler, class... Signatures>
struct op;

template <class Impl, class Work, class Handler>
struct op<Impl, Work, Handler> {
  template <class I, class W, class H>
  op(I&& impl, W&& work, H&& handler)
      : impl_(static_cast<I&&>(impl)),
        work_(static_cast<W&&>(work)),
        handler_(static_cast<H&&>(handler)) {
  }

  op(op&& other)
      : impl_(static_cast<Impl&&>(other.impl_)),
        work_(static_cast<Work&&>(other.work_)),
        handler_(static_cast<Handler&&>(other.handler_)) {
  }

  Impl impl_;
  Work work_;
  Handler handler_;
};

template <class Impl, class Work, class Handler, class R, class... Args>
struct op<Impl, Work, Handler, R(Args...)> : op<Impl, Work, Handler> {
  using op<Impl, Work, Handler>::op;

  void run() {
    this->impl_(*this);
  }
};

int main() {
  impl i;
  work w;
  handler h;
  op<impl, work, handler, void(int)> x(
      static_cast<impl&&>(i),
      static_cast<work&&>(w),
      static_cast<handler&&>(h));
  x.run();
  return 0;
}

// VALIDATION: compile-pass
// An inherited constructor template keeps deduction and defaulted enable-if
// participation when the derived type is a parameter-pack specialization.

template <bool B, class T = void>
struct enable_if {};

template <class T>
struct enable_if<true, T> {
  typedef T type;
};

template <class A, class B>
struct is_same {
  static const bool value = false;
};

template <class A>
struct is_same<A, A> {
  static const bool value = true;
};

template <class T>
struct remove_reference {
  typedef T type;
};

template <class T>
struct remove_reference<T &> {
  typedef T type;
};

template <class T>
struct remove_reference<T &&> {
  typedef T type;
};

struct first {};
struct second {};
struct third {};

template <class... Ts>
struct tuple_like {
private:
  struct tag {};

  tuple_like(tag, const Ts &...) {}

  template <class... Args>
  struct accepts_impl {
    static const bool value = true;
  };

  template <class First, class... Rest>
  struct accepts_impl<First, Rest...> {
    static const bool value =
        !is_same<typename remove_reference<First>::type, tag>::value;
  };

public:
  template <class... Args>
  using accepts = accepts_impl<Args...>;

  template <class... Args,
            typename enable_if<accepts<Args &&...>::value, int>::type = 0>
  tuple_like(Args &&... args)
      : tuple_like(tag(), static_cast<Args &&>(args)...) {}
};

template <class... Ts>
struct key : private tuple_like<Ts...> {
  using tuple_like<Ts...>::tuple_like;
};

int main()
{
  first a;
  second b;
  third c;
  key<first, second, third> value(a, b, c);
  (void)value;
  return 0;
}
